const path = require('path');
const ApiError = require('./ApiError');
const { UPLOADS_ROOT_DIR } = require('../middleware/upload');

/**
 * Turns a stored "/uploads/..." path into an absolute one, and refuses
 * anything that resolves outside the uploads directory. The stored paths are
 * generated by multer so they are already safe, but a single bad row must
 * never be able to hand out /etc/passwd or a .env file.
 */
function resolveUploadPath(publicPath) {
  if (typeof publicPath !== 'string' || publicPath.length === 0) {
    throw ApiError.notFound('File not found.');
  }

  const relative = publicPath.replace(/^\/uploads\//, '');
  const absolute = path.resolve(UPLOADS_ROOT_DIR, relative);
  const root = path.resolve(UPLOADS_ROOT_DIR);

  if (absolute !== root && !absolute.startsWith(root + path.sep)) {
    throw ApiError.notFound('File not found.');
  }

  return absolute;
}

module.exports = { resolveUploadPath };
